<script lang="ts">
 import {SUIT_THEMES,suitArtwork} from '$lib/art/card-theme';
 import {base} from '$app/paths';
 import GameCard from '$lib/components/GameCard.svelte';
 import {minor,suits,type Suit} from '$lib/data/game';
 let size=$state(220),indexStyle=$state<'numeric'|'traditional'>('traditional'),suit=$state('all'),grey=$state(false),sampleRank=$state(14),upsideDown=$state(false);
 const visible=$derived(minor.filter(c=>suit==='all'||c.suit===suit));
 const sample=$derived(minor.find(c=>c.suit===(suit==='all'?'Swords':suit)&&c.rank===Number(sampleRank))!);
 const fanCards=$derived(['Wands-0','Cups-9','Swords-10','Pentacles-11','Wands-12','Cups-13','Pentacles-0','Swords-9','Pentacles-13'].map(id=>minor.find(c=>c.id===id)!));
</script>
<svelte:head><title>Alternate card layout · Hell’s Bells</title></svelte:head>
